import { FormInput, Spacer, GradientButton, MaterialTextInput, INPUT_STATUS, Text, useTheme, useKeyboard, MaterialTextInputPropsMethod } from '@core/ui';
import React, { FC, useEffect, useRef, useState } from 'react';
import useCSS from '@src/presentation/style';
import { formatMoney } from '@src/utils/currency';
import { Image, InputModeOptions, Keyboard, SafeAreaView, TextInput, TextInputProps, View } from 'react-native';
import { ValidationResult } from '@src/utils/validator';
import { useTranslation } from '@core/service';
import getImg from '@src/utils/getImg';
interface Props {
    value: string;
    onSubmit: (text: string) => void;
    placeholder?: string;
    label?: string;
    inputType?: string;
    format?: string;
    validate?: (value: string) => ValidationResult;
    textInputProps?: TextInputProps;
    subText?: string;
}

interface ExtendTextInput extends TextInput, MaterialTextInputPropsMethod { }

const ContentInput: FC<Props> = ({ value, onSubmit, placeholder, label, inputType = 'default', format, validate, textInputProps, subText, ...props }) => {
    const css = useCSS();
    const { theme } = useTheme();
    const [displayValue, setDisplayValue] = useState(value);
    const [errorMessages, setErrorMessages] = useState<string>('');
    const { t } = useTranslation(['validator']);

    const { keyboardState } = useKeyboard();
    const [focus, setFocus] = useState(false);
    const inputRef = useRef<ExtendTextInput | null>(null);
    const handleInputWithFormat = (text: string) => {
        let value = text;
        if (inputType === 'numeric') {
            value = value.replace(/[^0-9]/g, '');
            console.log('\x1b[31m value', value);
        }
        switch (format) {
            case 'money':
                value = formatMoney(text?.replace(/[^0-9]/g, '') ?? '');
                break;
            default:
                break;
        }
        setDisplayValue(value || ' ');
    };
    const handleValidate = (value: string) => {
        const validation = validate?.(value);
        if (validation?.isEmpty) {
            setErrorMessages(validation.errors || '');
            return false;
        }
        if (validation?.isInvalid) {
            setErrorMessages(validation?.errors || '');
            return false;
        }
        return true;
    };
    const handleSubmit = () => {
        const isValid = handleValidate(displayValue);
        if (!isValid) {
            return;
        }
        let submitValue = displayValue;
        switch (format) {
            case 'money':
                submitValue = displayValue?.replaceAll?.(',', '');
                break;
            default:
                break;
        }
        onSubmit?.(submitValue);
        Keyboard.dismiss();
    };
    useEffect(() => {
        // const isValid = handleValidate(displayValue);
        if (displayValue) {
            setErrorMessages('');
        }
        console.log('\x1b[31m focus', focus);
    }, [displayValue, focus]);
    useEffect(() => {
        setTimeout(() => {
            if (inputRef) {
                inputRef?.current?.focus();
            }
        }, 350);
    }, []);
    return (
        <SafeAreaView>
            <Spacer height={16} />
            <MaterialTextInput
                ref={inputRef}
                label={label}
                placeholder={placeholder}
                // keyboardType={inputType}
                onChangeText={handleInputWithFormat}
                autoFocus={false}
                inputMode={(inputType as InputModeOptions) || 'text'}
                {...textInputProps}
                value={displayValue}
            />
            <View style={[css.row, css.items_center]}>
                {errorMessages && <Image source={getImg('/assets/images/icons/icon_error_input.png')} style={{ width: theme.Size.Horizontal.Regular, height: theme.Size.Vertical.Regular, resizeMode: 'contain', marginRight: theme.Size.Horizontal.Base }} />}
                {errorMessages ?
                    <Text style={{ ...theme.Typography.TextCaption100.Regular, color: theme.Colors.Text.Error }}>{t(`${errorMessages}`)}</Text> :
                    <Text style={{ ...theme.Typography.TextCaption100.Regular }}>{`${subText || ''}`}</Text>
                }
            </View>
            <Spacer height={56} />
            <GradientButton gradientProps={{ type: 'primary' }} title={t('btn_save')} onPress={handleSubmit} />
            <Spacer height={8} />
        </SafeAreaView>
    );
};
export default ContentInput;
